import React from 'react'
import Button from '../Button/Button'
import NewReleases from '../icons/NewReleases'
import Banner from './Banner'

export default {
  title: 'Components/Banner',
  component: Banner,
  argTypes: {
    actionLabels: {
      control: { type: 'object' },
    },
  },
}

function Template(args: {
  actionLabels: string[]
  description: string
}): JSX.Element {
  return (
    <Banner>
      <Banner.Content>
        <Banner.StartAdornment>
          <NewReleases />
        </Banner.StartAdornment>
        <Banner.Description>{args.description}</Banner.Description>
      </Banner.Content>
      {args.actionLabels.length ? (
        <Banner.Actions>
          {args.actionLabels.map((label) => (
            <Button color="primary" key={label} variant="text">
              {label}
            </Button>
          ))}
        </Banner.Actions>
      ) : null}
    </Banner>
  )
}

export const Default = {
  render: Template,
  args: {
    description: 'This is short a description',
    actionLabels: ['Go back', 'Learn More', 'Send Feedback'],
  },
}
